// SECURITY LAYER 1: Country Code Filter
const input = $input.first().json;
const phone = input.phoneNumberFormatted;

const ALLOWED_COUNTRY_CODES = ['91','61'];
const isAllowedCountry = ALLOWED_COUNTRY_CODES.some(code => phone.startsWith(code));

if (!isAllowedCountry) {
  return { ...input, securityCheck: 'REJECTED', rejectReason: 'country_not_allowed', silent: true };
}

return { ...input, securityCheck: 'PASSED_COUNTRY', countryCode: phone.substring(0, 3) };

// WF-01: Prepare User Data
// Prepares all data needed for WF-02 routing
const securityData = $('Layer 3 : Blacklisted Users Filter').first().json;
const userResult = $('Load User').first().json;

// ── Pending user lookup ───────────────────────────────────────────────────────
let pendingUserData = null;
try {
  const pendingResult = $('Load Pending User').first().json;
  if (pendingResult && pendingResult.phone_number) {
    pendingUserData = {
      phoneNumber: pendingResult.phone_number,
      contactName: pendingResult.contact_name,
      createdAt: pendingResult.created_at
    };
  }
} catch(e) {
  // Node may not have run or returned no rows — treat as null
}

// ── User lookup ───────────────────────────────────────────────────────────────
const userExists = userResult && userResult.id;
let userData = null;
if (userExists) {
  let contextObj = {};
  try {
    contextObj = typeof userResult.context === 'string'
      ? JSON.parse(userResult.context)
      : (userResult.context || {});
  } catch(e) {
    console.error('Error parsing user context:', e);
  }
  userData = {
    id: userResult.id,
    phoneNumber: userResult.phone_number,
    name: userResult.name,
    dateOfBirth: userResult.date_of_birth,
    timeOfBirth: userResult.time_of_birth,
    placeOfBirth: userResult.place_of_birth,
    status: userResult.status,
    currentConsultationId: userResult.current_consultation_id,
    totalConsultations: userResult.total_consultations,
    context: contextObj,
    createdAt: userResult.created_at,
    updatedAt: userResult.updated_at,
    lastMessageAt: userResult.last_message_at,
    awaitingFeedback: userResult.awaiting_feedback,
    blockedAt: userResult.blocked_at,
    blockedBy: userResult.blocked_by,
    blockedReason: userResult.blocked_reason
  };
}

// ── Return combined data for WF-02 ────────────────────────────────────────────
return {
  messageId: securityData.messageId,
  phoneNumber: securityData.phoneNumber,
  phoneNumberFormatted: securityData.phoneNumberFormatted,
  contactName: securityData.contactName,
  messageType: securityData.messageType,
  messageContent: securityData.messageContent,
  messageContentUpper: securityData.messageContentUpper,
  rawMessage: securityData.rawMessage,
  timestamp: securityData.timestamp,
  metadata: securityData.metadata,

  // User state
  isNewUser: !userExists && !pendingUserData,
  user: userData,
  pendingUser: pendingUserData
};

