// Node: Filter Message Types
const input = $input.first().json;
const messageType = input.messageType; // From WhatsApp webhook

// Allowed types for Chinmay Astro
const ALLOWED_TYPES = [
  'text',           // Regular text messages
  'interactive'     // Form submissions, button responses
];

// Check if message type is allowed
const isAllowed = ALLOWED_TYPES.includes(messageType);

return {
  ...input,
  messageTypeAllowed: isAllowed,
  messageTypeReason: isAllowed ? 'Allowed type' : `Rejected type: ${messageType}`
};

const input = $('Layer 2: Non-Text Message Filter').first().json;
const blacklistResult = $input.first().json;

if (blacklistResult && blacklistResult.id) {
  if (blacklistResult.status === 'opted_out') {
    return { ...input, securityCheck: 'OPTED_OUT', rejectReason: 'opted_out', silent: true };
  }
  return { ...input, securityCheck: 'REJECTED', rejectReason: 'blacklisted', silent: true };
}

return { ...input, securityCheck: 'PASSED_BLACKLIST' };

